{
    "message": {
        "token": "{{fcm_token}}",
        "android": {
            "priority": "high"
        },
        "apns": {
            "headers": {
                "apns-push-type": "background",
                "apns-priority": "5"
            },
            "payload": {
                "aps": {
                    "content-available": 1
                }
            }
        },
        "data": {
            "content.id": "1",
            "content.badge": "50",
            "content.channelKey": "push",
            "content.displayOnForeground": "true",
            "content.notificationLayout": "BigPicture",
            "content.largeIcon": "https://raw.githubusercontent.com/rafaelsetragni/awesome_notifications/2f5a5346f36cfea0b8d221062b32a54ae309339f/example/assets/images/awesome-notifications-logo-color.png",
